arguments.keystrokes:
cat > /etc/ssh/sshd_config.d/git-server.conf <<'EOF'
PasswordAuthentication yes
KbdInteractiveAuthentication no
PermitRootLogin no
UsePAM yes
EOF
mkdir -p /etc/ssl/git-server
openssl req -x509 -nodes -newkey rsa:2048 -days 3650 \
  -keyout /etc/ssl/git-server/server.key \
  -out /etc/ssl/git-server/server.crt \
  -subj '/CN=localhost' \
  -addext 'subjectAltName=DNS:localhost,IP:127.0.0.1'
chmod 600 /etc/ssl/git-server/server.key
cat > /etc/nginx/sites-available/git-https <<'EOF'
server {
    listen 8443 ssl;
    listen [::]:8443 ssl;
    server_name localhost;
    root /var/www/html;
    index index.html;
    ssl_certificate /etc/ssl/git-server/server.crt;
    ssl_certificate_key /etc/ssl/git-server/server.key;
    location / {
        try_files $uri $uri/ =404;
    }
}
EOF
rm -f /etc/nginx/sites-enabled/default
ln -sf /etc/nginx/sites-available/git-https /etc/nginx/sites-enabled/git-https
nginx -t

mkdir -p /run/sshd /etc/ssh/sshd_config.d /etc/ssl/git-server /var/www/html/dev
printf 'git:password\n' | chpasswd
cat > /etc/ssh/sshd_config.d/git-server.conf <<'EOF'
PasswordAuthentication yes
KbdInteractiveAuthentication no
UsePAM yes
EOF
if [ ! -s /etc/ssl/git-server/server.key ] || [ ! -s /etc/ssl/git-server/server.crt ]; then openssl req -x509 -nodes -newkey rsa:2048 -days 3650 -keyout /etc/ssl/git-server/server.key -out /etc/ssl/git-server/server.crt -subj '/CN=localhost' -addext 'subjectAltName=DNS:localhost,IP:127.0.0.1'; fi
chmod 600 /etc/ssl/git-server/server.key
cat > /etc/nginx/sites-available/git-https <<'EOF'
server {
    listen 8443 ssl;
    listen [::]:8443 ssl;
    server_name localhost;
    root /var/www/html;
    ssl_certificate /etc/ssl/git-server/server.crt;
    ssl_certificate_key /etc/ssl/git-server/server.key;
    location / { try_files $uri $uri/ =404; }
}
EOF
rm -f /etc/nginx/sites-enabled/default
ln -sf /etc/nginx/sites-available/git-https /etc/nginx/sites-enabled/git-https
nginx -t
